mapper.select:
select id,
sole_name as soleName,
sole_fields as soleFields,
sole_cycle_times as soleCycleTimes,
status,
DATE_FORMAT(bsrc.create_time,'%Y-%m-%d %H:%i:%s') as createTime,
DATE_FORMAT(bsrc.update_time,'%Y-%m-%d %H:%i:%s') as updateTime
from b_sole_rule_config bsrc
where bsrc.is_del = 1

    and bsrc.status = #{status}


    and bsrc.sole_name like concat("%", #{soleName},"%")


      and bsrc.create_time >=#{createTimeStart} 


      and bsrc.create_time <#{createTimeEnd} 


      and bsrc.update_time >=#{updateTimeStart} 


      and bsrc.update_time <#{updateTimeEnd} 

order by bsrc.create_time desc

select count(*) from b_sole_rule_config c,b_customer_sole s where c.id=s.sole_id
and c.is_del=1 and s.is_del=1

    and c.sole_fields = #{soleFields}


    and c.sole_cycle_times = #{soleCycleTimes}


    and s.customer_id=#{cid}


    and s.condition_info=#{conditionInfo}


    and s.sole_id!=#{soleId} and c.id!=#{soleId}


    and s.all_user_type != #{allUserType}
